#define _POSIX_C_SOURCE 199309L
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

timer_t global_timerid;

// Signal handler required for context, but its actions are minimal here.
static void timer_handler(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    // printf("Timer fired.\n");
}

int main() {
    struct sigevent sev;
    struct sigaction sa;

    // 1. Set up signal handler (required for timer_create)
    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGRTMIN, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // 2. Set up sigevent structure
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &global_timerid;

    // 3. Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, &global_timerid) == -1) {
        perror("timer_create");
        return EXIT_FAILURE;
    }
    printf("Timer successfully created with ID: %p\n", (void*)global_timerid);

    // 4. Delete the timer
    printf("Attempting to delete timer ID %p...\n", (void*)global_timerid);
    if (timer_delete(global_timerid) == -1) {
        perror("timer_delete failed");
        return EXIT_FAILURE;
    }
    printf("Timer successfully deleted.\n");

    // 5. Demonstrate error handling (attempting to delete an invalid ID)
    printf("Attempting deletion again (should fail with EINVAL)...\n");
    if (timer_delete(global_timerid) == -1) {
        if (errno == EINVAL) {
            printf("Second delete failed as expected: EINVAL.\n");
        } else {
            perror("Second delete failed unexpectedly");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}
